-- Generated by tools/generate.py from bricksurance-data-core model v0.9.0.
-- Do not edit: change the spec in model/ and regenerate.

CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.underwriting_metrics
COMMENT 'Certified underwriting KPIs - premium, claims development and loss ratio - defined once over the canonical model. Measures are in original transaction currency: always group by or filter on currency_code before summing money. Query measures with MEASURE(name).'
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1

source: lr_serverless_aws_us_catalog.bricksurance_semantics.financial_transaction

joins:
  - name: line_of_business
    source: lr_serverless_aws_us_catalog.bricksurance_reference.line_of_business
    on: source.line_of_business_code = line_of_business.line_of_business_code

dimensions:
  - name: underwriting_year
    expr: underwriting_year
  - name: line_of_business
    expr: line_of_business.label
  - name: line_of_business_code
    expr: source.line_of_business_code
  - name: currency_code
    expr: currency_code
  - name: transaction_month
    expr: DATE_TRUNC('MONTH', transaction_date)
  - name: cause_of_loss_code
    expr: cause_of_loss_code

measures:
  - name: gross_written_premium
    expr: SUM(CASE WHEN transaction_kind = 'PREMIUM' THEN amount ELSE 0 END)
  - name: claims_paid
    expr: SUM(CASE WHEN transaction_type_code IN ('INDEMNITY_PAYMENT', 'EXPENSE_PAYMENT') THEN amount ELSE 0 END)
  - name: recoveries
    expr: SUM(CASE WHEN transaction_type_code = 'RECOVERY' THEN amount ELSE 0 END)
  - name: outstanding_reserve
    expr: SUM(CASE WHEN transaction_type_code = 'CASE_RESERVE_MOVEMENT' THEN amount ELSE 0 END)
  - name: claims_incurred
    expr: SUM(CASE WHEN transaction_kind = 'CLAIM' THEN amount ELSE 0 END)
  - name: loss_ratio_written
    expr: SUM(CASE WHEN transaction_kind = 'CLAIM' THEN amount ELSE 0 END) / NULLIF(SUM(CASE WHEN transaction_kind = 'PREMIUM' THEN amount ELSE 0 END), 0)
  - name: policy_count
    expr: COUNT(DISTINCT CASE WHEN transaction_kind = 'PREMIUM' THEN policy_id END)
  - name: claim_count
    expr: COUNT(DISTINCT claim_id)
$$;
